def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    recent = opp[-8:]
    rc = sum(1 for x in recent if x == 'C')
    rd = len(recent) - rc
    coop_rate = opp_c / n
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'
    if coop_rate >= 0.85 and n >= 4:
        if last_opp == 'D':
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'C':
        if len(opp) >= 2 and opp[-2] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.85 else 'C'
    if last_opp == 'D' and last_me == 'D':
        if rd >= 5:
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if n >= 6:
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            return 'D'
        if streak == 2 and rng.random() < 0.7:
            return 'D'
    if rc >= 6 and coop_rate >= 0.5:
        if rng.random() < 0.05:
            return 'D'
        return 'C'
    if rd >= 3 and rc >= 2:
        if rng.random() < 0.85:
            return 'C'
        return 'D'
    if opp_d == 0:
        return 'C'
    if coop_rate >= 0.6:
        return 'C'
    if coop_rate <= 0.25:
        return 'D'
    if last_opp == 'C':
        return 'C'
    if rng.random() < 0.5:
        return 'C'
    return 'D'
